1	"use client";
2	
3	import {
4	  createContext,
5	  useCallback,
6	  useContext,
7	  useEffect,
8	  useMemo,
9	  useRef,
10	  useState,
11	  type ReactNode,
12	} from "react";
13	import type { ParsedFeature, ParsedTask } from "@/services/yaml-parser";
14	import type { StoredWorkspace } from "@/types/workspace";
15	import { useBoardData, type UseBoardDataOptions } from "../../hooks/useBoardData";
16	import { usePullRequestTaskData } from "../../hooks/usePullRequestTaskData";
17	import type { ActiveFilters, BoardLoadError } from "../../types";
18	import {
19	  getDefaultStatusFilter,
20	  getStoredStatusFilter,
21	  saveStatusFilter,
22	} from "../../lib/status-filter-store";
23	
24	export type SelectedTask = {
25	  task: ParsedTask;
26	  featureId: string;
27	  featureTitle: string;
28	} | null;
29	
30	export type BoardContextValue = {
31	  workspace: StoredWorkspace;
32	  features: ParsedFeature[];
33	  trackedFeatures: ParsedFeature[];
34	  loading: boolean;
35	  error: BoardLoadError | null;
36	  reload: () => void;
37	  searchQuery: string;
38	  setSearchQuery: (query: string) => void;
39	  activeFilters: ActiveFilters;
40	  setActiveFilters: (filters: ActiveFilters) => void;
41	  expandedFeatureIds: Set<string>;
42	  toggleFeature: (featureId: string) => void;
43	  selectedTask: SelectedTask;
44	  setSelectedTask: (task: SelectedTask) => void;
45	};
46	
47	const BoardContext = createContext<BoardContextValue | null>(null);
48	
49	export type BoardProviderProps = {
50	  workspace: StoredWorkspace;
51	  children: ReactNode;
52	} & UseBoardDataOptions;
53	
54	export function BoardProvider({
55	  workspace,
56	  children,
57	  clientFactory,
58	}: BoardProviderProps) {
59	  const { features, loading, error, reload } = useBoardData(workspace, {
60	    clientFactory,
61	  });
62	  const {
63	    trackedFeatures,
64	    reload: reloadTracking,
65	  } = usePullRequestTaskData(workspace, {
66	    clientFactory,
67	  });
68	
69	  const [searchQuery, setSearchQuery] = useState("");
70	  const [activeFilters, setActiveFilters] = useState<ActiveFilters>(() => ({
71	    statuses: getStoredStatusFilter() ?? getDefaultStatusFilter(),
72	  }));
73	  const [expandedFeatureIds, setExpandedFeatureIds] = useState<Set<string>>(
74	    () => new Set(),
75	  );
76	  const [selectedTask, setSelectedTask] = useState<SelectedTask>(null);
77	
78	  const toggleFeature = useCallback((featureId: string) => {
79	    setExpandedFeatureIds((prev) => {
80	      const next = new Set(prev);
81	      if (next.has(featureId)) {
82	        next.delete(featureId);
83	      } else {
84	        next.add(featureId);
85	      }
86	      return next;
87	    });
88	  }, []);
89	
90	  const reloadAll = useCallback(() => {
91	    reload();
92	    reloadTracking();
93	  }, [reload, reloadTracking]);
94	
95	  const reloadAllRef = useRef(reloadAll);
96	  useEffect(() => {
97	    reloadAllRef.current = reloadAll;
98	  }, [reloadAll]);
99	
100	  useEffect(() => {
101	    const id = setInterval(() => {
102	      reloadAllRef.current();
103	    }, 60_000);
104	    return () => clearInterval(id);
105	  }, []);
106	
107	  const handleSetActiveFilters = useCallback((filters: ActiveFilters) => {
108	    saveStatusFilter(filters.statuses);
109	    setActiveFilters(filters);
110	  }, []);
111	
112	  const value = useMemo<BoardContextValue>(
113	    () => ({
114	      workspace,
115	      features,
116	      trackedFeatures,
117	      loading,
118	      error,
119	      reload: reloadAll,
120	      searchQuery,
121	      setSearchQuery,
122	      activeFilters,
123	      setActiveFilters: handleSetActiveFilters,
124	      expandedFeatureIds,
125	      toggleFeature,
126	      selectedTask,
127	      setSelectedTask,
128	    }),
129	    [
130	      workspace,
131	      features,
132	      trackedFeatures,
133	      loading,
134	      error,
135	      reloadAll,
136	      searchQuery,
137	      activeFilters,
138	      handleSetActiveFilters,
139	      expandedFeatureIds,
140	      toggleFeature,
141	      selectedTask,
142	    ],
143	  );
144	
145	  return <BoardContext.Provider value={value}>{children}</BoardContext.Provider>;
146	}
147	
148	export function useBoardContext(): BoardContextValue {
149	  const ctx = useContext(BoardContext);
150	  if (!ctx) {
151	    throw new Error("useBoardContext must be used within a BoardProvider");
152	  }
153	  return ctx;
154	}
