66	function BoardControls() {
67	  const {
68	    loading,
69	    reload,
70	    searchQuery,
71	    setSearchQuery,
72	    activeFilters,
73	    setActiveFilters,
74	  } = useBoardContext();
75	  const [filterOpen, setFilterOpen] = useState(false);
76	  const filterRef = useRef<HTMLDivElement>(null);
77	  const selectedStatuses = new Set(activeFilters.statuses);
78	  const allSelected = isAllStatusFilterSelected(activeFilters.statuses);
79	
80	  useEffect(() => {
81	    if (!filterOpen) return;
