138	        >
139	          <Funnel className="h-3.5 w-3.5" aria-hidden="true" />
140	          Filter
141	        </button>
142	        {filterOpen && (
143	          <div
144	            role="menu"
145	            className="absolute right-0 top-9 z-30 w-48 border border-border bg-surface p-2 shadow-lg"
146	          >
147	            <label className="mb-1 flex cursor-pointer items-center gap-2 border-b border-border px-2 py-1.5 pb-2 text-xs font-semibold text-text-primary hover:bg-surface-subtle">
148	              <input
149	                type="checkbox"
150	                checked={allSelected}
151	                onChange={toggleAllStatuses}
152	                className="h-3 w-3 accent-primary"
