182	export function KanbanBoard() {
183	  const {
184	    features,
185	    loading,
186	    error,
187	    searchQuery,
188	    activeFilters,
189	    expandedFeatureIds,
190	    toggleFeature,
191	    setSelectedTask,
192	  } = useBoardContext();
193	
194	  const visibleFeatures = useMemo(
195	    () =>
196	      features.filter(
197	        (f) =>
198	          matchesSearch(f, searchQuery) &&
199	          matchesStatusFilter(f, activeFilters.statuses),
200	      ),
201	    [features, searchQuery, activeFilters],
202	  );
203	
204	  const columnCounts = useMemo(() => {
205	    const counts: Record<string, number> = {};
206	    for (const col of STATUS_COLUMNS) counts[col.key] = 0;
207	    for (const feature of visibleFeatures) {
208	      for (const task of feature.tasks) {
209	        if (task.status in counts) counts[task.status]++;
210	      }
211	    }
212	    return counts;
213	  }, [visibleFeatures]);
214	
215	  let content;
216	  if (loading) {
217	    content = (
218	      <div className="flex flex-1 items-center justify-center">
219	        <p className="text-sm text-text-muted">Loading board...</p>
220	      </div>
221	    );
222	  } else if (error) {
223	    if (error.kind === "access_denied") {
224	      content = <AccessDeniedState message={error.message} />;
225	    } else if (error.kind === "not_found") {
226	      content = <NoWorkflowDataState message={error.message} />;
227	    } else if (error.kind === "parse_error") {
228	      content = <ParseErrorState message={error.message} />;
229	    } else {
230	      content = <NetworkErrorState message={error.message} />;
231	    }
232	  } else if (features.length === 0) {
233	    content = <EmptyBoardState />;
234	  } else if (visibleFeatures.length === 0) {
235	    content = (
236	      <EmptyState message="No features match the current search or filters." />
237	    );
238	  } else {
239	    content = (
240	      <div className="min-h-0 flex-1 overflow-auto">
241	        <div
242	          className="w-full"
243	          style={{ minWidth: MIN_COLUMN_WIDTH * STATUS_COLUMNS.length }}
244	        >
245	          <div
246	            className="sticky top-0 z-10 flex w-full border-b border-border"
247	            role="row"
248	            aria-label="Status columns"
249	          >
250	            {STATUS_COLUMNS.map((col) => (
251	              <ColumnHeader
252	                key={col.key}
253	                label={col.label}
254	                color={col.color}
255	                count={columnCounts[col.key] ?? 0}
256	              />
257	            ))}
258	          </div>
259	
260	          <div role="list" aria-label="Features" className="bg-surface">
261	            {visibleFeatures.map((feature) => (
262	              <div key={feature.id} role="listitem">
263	                <FeatureRow
264	                  feature={feature}
265	                  isExpanded={expandedFeatureIds.has(feature.id)}
266	                  onToggle={() => toggleFeature(feature.id)}
267	                  onSelectTask={setSelectedTask}
268	                  minColumnWidth={MIN_COLUMN_WIDTH}
269	                />
270	              </div>
271	            ))}
272	          </div>
273	        </div>
274	      </div>
275	    );
276	  }
277	
278	  return (
279	    <div className="flex h-full min-h-0 flex-1 flex-col overflow-hidden border border-border bg-surface">
280	      <BoardControls />
281	      {content}
282	    </div>
283	  );
284	}
