1	import type { ParsedFeature } from "@/services/yaml-parser";
2	
3	export function matchesSearch(feature: ParsedFeature, query: string): boolean {
4	  if (!query) return true;
5	  const q = query.toLowerCase();
6	  if (feature.title.toLowerCase().includes(q)) return true;
7	  if (feature.id.toLowerCase().includes(q)) return true;
8	  return feature.tasks.some(
9	    (t) =>
10	      t.title.toLowerCase().includes(q) || t.id.toLowerCase().includes(q),
11	  );
12	}
13	
14	export function matchesStatusFilter(
15	  feature: ParsedFeature,
16	  statuses: string[],
17	): boolean {
18	  if (statuses.length === 0) return true;
19	  return feature.tasks.some((t) => statuses.includes(t.status));
20	}
