1	export type TaskStatus =
2	  | "todo"
3	  | "ready"
4	  | "in_progress"
5	  | "blocked"
6	  | "in_review"
7	  | "done"
8	  | "cancelled";
9	
10	export type StatusColumn = {
11	  key: TaskStatus;
12	  label: string;
13	  color: string;
14	};
15	
16	export const STATUS_COLUMNS: StatusColumn[] = [
17	  { key: "todo", label: "TODO", color: "#3274b4" },
18	  { key: "ready", label: "READY", color: "#6e6de7" },
19	  { key: "in_progress", label: "IN PROGRESS", color: "#e08500" },
20	  { key: "blocked", label: "BLOCKED", color: "#e62a34" },
21	  { key: "in_review", label: "IN REVIEW", color: "#8e67cb" },
22	  { key: "done", label: "DONE", color: "#009252" },
23	  { key: "cancelled", label: "CANCELLED", color: "#5c636e" },
24	];
25	
26	export const STATUS_COLOR: Record<string, string> = Object.fromEntries(
27	  STATUS_COLUMNS.map((c) => [c.key, c.color]),
28	);
29	
30	export const NEXT_ACTIONS: Record<string, string> = {
31	  todo: "Auto-ready when last dependency is done",
32	  ready: "Start implementation",
33	  in_progress: "Waiting for result",
34	  blocked: "Human resolves",
35	  in_review: "Human approves or rejects",
36	  done: "",
37	  cancelled: "Do nothing",
38	};
39	
40	export function getStatusColor(status: string): string {
41	  return STATUS_COLOR[status] ?? "#8892b5";
42	}
43	
44	export function getNextAction(status: string): string {
45	  return NEXT_ACTIONS[status] ?? "";
46	}
47	
48	export function getStatusLabel(status: string): string {
49	  return STATUS_COLUMNS.find((c) => c.key === status)?.label ?? status.toUpperCase().replace(/_/g, " ");
50	}
51	
52	const FEATURE_STATUS_LABELS: Record<string, string> = {
53	  in_design: "In Design",
54	  in_tdd: "In TDD",
55	  ready_for_implementation: "Ready",
56	  in_implementation: "In Progress",
57	  in_handoff: "In Handoff",
58	  done: "Done",
59	  blocked: "Blocked",
60	  cancelled: "Cancelled",
61	};
62	
63	const FEATURE_STATUS_COLORS: Record<string, string> = {
64	  in_design: "#3274b4",
65	  in_tdd: "#3274b4",
66	  ready_for_implementation: "#6e6de7",
67	  in_implementation: "#e08500",
68	  in_handoff: "#8e67cb",
69	  done: "#009252",
70	  blocked: "#e62a34",
71	  cancelled: "#5c636e",
72	};
73	
74	export function getFeatureStatusLabel(status: string): string {
75	  return FEATURE_STATUS_LABELS[status] ?? status;
76	}
77	
78	export function getFeatureStatusColor(status: string): string {
79	  return FEATURE_STATUS_COLORS[status] ?? "#8892b5";
80	}
81	
82	const FEATURE_NEXT_ACTION_PRIORITY: TaskStatus[] = [
83	  "blocked",
84	  "in_review",
85	  "in_progress",
86	  "ready",
87	  "todo",
88	];
89	
90	export function getFeatureNextAction(tasks: Array<{ status: string }>): string | null {
91	  for (const status of FEATURE_NEXT_ACTION_PRIORITY) {
92	    if (tasks.some((t) => t.status === status)) {
93	      return NEXT_ACTIONS[status] ?? null;
94	    }
95	  }
96	  return null;
97	}
