1	import { STATUS_COLUMNS, type TaskStatus } from "./status";
2	
3	const STORAGE_KEY = "dashboard:board-status-filter";
4	
5	const VALID_STATUSES = new Set<string>(STATUS_COLUMNS.map((s) => s.key));
6	
7	function isValidStatusArray(value: unknown): value is TaskStatus[] {
8	  return (
9	    Array.isArray(value) &&
10	    value.every((v) => typeof v === "string" && VALID_STATUSES.has(v))
11	  );
12	}
13	
14	export function getDefaultStatusFilter(): TaskStatus[] {
15	  return STATUS_COLUMNS.filter((s) => s.key !== "done").map((s) => s.key);
16	}
17	
18	export function getStoredStatusFilter(): TaskStatus[] | null {
19	  if (typeof window === "undefined") return null;
20	  try {
21	    const raw = localStorage.getItem(STORAGE_KEY);
22	    if (raw === null) return null;
23	    const parsed: unknown = JSON.parse(raw);
24	    return isValidStatusArray(parsed) ? parsed : null;
25	  } catch {
26	    return null;
27	  }
28	}
29	
30	export function saveStatusFilter(statuses: string[]): void {
31	  if (typeof window === "undefined") return;
32	  try {
33	    localStorage.setItem(STORAGE_KEY, JSON.stringify(statuses));
34	  } catch {
35	    // Ignore storage failures so the board remains usable in restricted browsers.
36	  }
37	}
