1	import { STATUS_COLUMNS, type TaskStatus } from "./status";
2	
3	export function getAllStatusFilterKeys(): TaskStatus[] {
4	  return STATUS_COLUMNS.map((status) => status.key);
5	}
6	
7	export function isAllStatusFilterSelected(
8	  selectedStatuses: readonly string[],
9	): boolean {
10	  const selected = new Set(selectedStatuses);
11	  return getAllStatusFilterKeys().every((status) => selected.has(status));
12	}
13	
14	export function toggleAllStatusFilter(
15	  selectedStatuses: readonly string[],
16	): TaskStatus[] {
17	  return isAllStatusFilterSelected(selectedStatuses)
18	    ? []
19	    : getAllStatusFilterKeys();
20	}
21	
22	export function toggleStatusFilter(
23	  selectedStatuses: readonly string[],
24	  status: string,
25	): string[] {
26	  const next = new Set(selectedStatuses);
27	  if (next.has(status)) {
28	    next.delete(status);
29	  } else {
30	    next.add(status);
31	  }
32	  return Array.from(next);
33	}
