export type BoardProviderProps = {
  workspace: StoredWorkspace;
  children: ReactNode;
} & UseBoardDataOptions;

export function BoardProvider({
  workspace,
  children,
  clientFactory,
}: BoardProviderProps) {
  const { features, loading, error, reload } = useBoardData(workspace, {
    clientFactory,
  });
  const {
    trackedFeatures,
    reload: reloadTracking,
  } = usePullRequestTaskData(workspace, {
    clientFactory,
  });

  const [searchQuery, setSearchQuery] = useState("");
  const [activeFilters, setActiveFilters] = useState<ActiveFilters>(() => ({
    statuses: getStoredStatusFilter() ?? getDefaultStatusFilter(),
  }));
  const [expandedFeatureIds, setExpandedFeatureIds] = useState<Set<string>>(
    () => new Set(),
  );
  const [selectedTask, setSelectedTask] = useState<SelectedTask>(null);

  const toggleFeature = useCallback((featureId: string) => {
    setExpandedFeatureIds((prev) => {
      const next = new Set(prev);
      if (next.has(featureId)) {
        next.delete(featureId);
      } else {
        next.add(featureId);
      }
      return next;
    });
  }, []);

  const reloadAll = useCallback(() => {
    reload();
    reloadTracking();
  }, [reload, reloadTracking]);

  const reloadAllRef = useRef(reloadAll);
  useEffect(() => {
    reloadAllRef.current = reloadAll;
  }, [reloadAll]);

  useEffect(() => {
    const id = setInterval(() => {
      reloadAllRef.current();
    }, 60_000);
    return () => clearInterval(id);
  }, []);

  const handleSetActiveFilters = useCallback((filters: ActiveFilters) => {
    saveStatusFilter(filters.statuses);
    setActiveFilters(filters);
  }, []);

  const value = useMemo<BoardContextValue>(
    () => ({
      workspace,
      features,
      trackedFeatures,
      loading,
      error,
      reload: reloadAll,
      searchQuery,
      setSearchQuery,
      activeFilters,
      setActiveFilters: handleSetActiveFilters,
      expandedFeatureIds,
      toggleFeature,
      selectedTask,
      setSelectedTask,
    }),
    [
      workspace,
      features,
      trackedFeatures,
      loading,
      error,
      reloadAll,
      searchQuery,
      activeFilters,
      handleSetActiveFilters,
      expandedFeatureIds,
      toggleFeature,
      selectedTask,
    ],
  );

  return <BoardContext.Provider value={value}>{children}</BoardContext.Provider>;
}

export function useBoardContext(): BoardContextValue {
  const ctx = useContext(BoardContext);
  if (!ctx) {
    throw new Error("useBoardContext must be used within a BoardProvider");
  }
  return ctx;
}

