"use client";

import { useEffect, useId } from "react";
import { Clock3, Layers3, X } from "lucide-react";
import type { ParsedFeature } from "@/services/yaml-parser";
import { formatTimestamp, getFeatureLastModifiedAt } from "@/lib/time";
import { getFeatureStatusColor, getFeatureStatusLabel } from "../../lib/status";

export type FeatureDetailSheetProps = {
  feature: ParsedFeature | null;
  onClose: () => void;
};

function FeatureStatusPill({ status }: { status: string }) {
  const color = getFeatureStatusColor(status);
  const label = getFeatureStatusLabel(status);
  return (
    <span
      className="inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium"
      style={{
        color,
        background: `${color}18`,
        border: `1px solid ${color}40`,
      }}
    >
      <span
        className="h-1.5 w-1.5 rounded-full"
        style={{ background: color }}
        aria-hidden="true"
      />
      {label}
    </span>
  );
}

function MetaRow({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex items-start gap-3 py-2.5 border-b border-border last:border-b-0">
      <span className="w-32 shrink-0 text-xs font-medium text-text-muted">{label}</span>
      <span className="min-w-0 flex-1 text-xs text-text-primary">{children}</span>
    </div>
  );
}

export function FeatureDetailSheet({ feature, onClose }: FeatureDetailSheetProps) {
  const open = feature !== null;
  const titleId = useId();

  useEffect(() => {
    if (!open) return;
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", handleKey);
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", handleKey);
      document.body.style.overflow = previousOverflow;
    };
  }, [open, onClose]);

  const lastModifiedAt = feature ? getFeatureLastModifiedAt(feature) : null;

  return (
    <div
      aria-hidden={!open}
      className={
        "fixed inset-0 z-40 " +
        (open ? "pointer-events-auto" : "pointer-events-none")
      }
    >
      <button
        type="button"
        aria-label="Close feature detail"
        tabIndex={open ? 0 : -1}
        onClick={onClose}
        className={
          "absolute inset-0 cursor-default bg-black/80 transition-opacity duration-200 " +
          (open ? "opacity-100" : "opacity-0")
        }
      />
      <aside
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className={
          "absolute right-0 top-0 flex h-full w-full flex-col bg-surface shadow-xl transition-transform duration-200 ease-out " +
          "sm:max-w-md " +
          (open ? "translate-x-0" : "translate-x-full")
        }
      >
        <header className="flex shrink-0 items-center justify-between border-b border-border px-5 py-4">
          <div className="flex min-w-0 items-center gap-3">
            <Layers3 className="h-4 w-4 shrink-0 text-success" aria-hidden="true" />
            <h2
              id={titleId}
              className="min-w-0 truncate text-sm font-semibold text-text-primary"
            >
              {feature?.title || feature?.id || "Feature Details"}
            </h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close feature detail"
            tabIndex={open ? 0 : -1}
            className="ml-3 shrink-0 rounded p-1 text-text-muted transition-colors hover:bg-surface-subtle hover:text-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary"
          >
            <X className="h-4 w-4" aria-hidden="true" />
          </button>
        </header>

        {feature && (
          <div className="flex-1 overflow-y-auto px-5 py-4">
            <div className="mb-5">
              <p className="text-xs font-medium text-text-muted mb-1">Feature ID</p>
              <p className="text-sm font-semibold font-mono text-text-primary">{feature.id}</p>
            </div>

            <div className="border-t border-border">
              <MetaRow label="Status">
                <FeatureStatusPill status={feature.featureStatus} />
              </MetaRow>
              {lastModifiedAt && (
                <MetaRow label="Last modified">
                  <span className="flex items-center gap-1.5 text-xs text-text-secondary">
                    <Clock3 className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                    {formatTimestamp(lastModifiedAt)}
                  </span>
                </MetaRow>
              )}
              <MetaRow label="Total tasks">
                <span className="text-xs text-text-secondary">
                  {feature.tasks.length} task{feature.tasks.length !== 1 ? "s" : ""}
                </span>
              </MetaRow>
            </div>
          </div>
        )}
      </aside>
    </div>
  );
}

